  //         (prevTime) => prevTime + 10;
  //       }, 10);
  //     } else if (!runningGender) {
  //       clearInterval(interval);
  //     }
  //     return () => clearInterval(interval);
  //   }
  // }, [running]);
  return (
    <div className="App">
      {genders.map((gender) => (
        <Fragment>
          <Stopwatch
            display={gender.display}
            key={gender.id}
            time={gender.time}
            // running={genders[gender].running}
          />
          <button onClick={() => startGender(gender.id)}>
            Start {gender.display}
          </button>
        </Fragment>
      ))}
    </div>
  );
}

export default App;
